import time

# Parse the Retry-After header from an HTTP response.
# The header can be either a number of seconds or an HTTP date.
# Returns the number of seconds to wait.
# If the header is missing or invalid, returns None.

def parse_retry_after(headers: dict) -> int | None:
    retry_after = headers.get("Retry-After")
    if retry_after is None:
        return None
    # Try to parse as integer seconds
    try:
        return int(retry_after)
    except ValueError:
        pass
    # Try to parse as HTTP date
    try:
        # Parse the date string into a datetime object
        dt = datetime.datetime.strptime(retry_after, "%a, %d %b %Y %H:%M:%S GMT")
        # Calculate the difference between the parsed date and now
        now = datetime.datetime.utcnow()
        delta = dt - now
        return int(delta.total_seconds())
    except Exception:
        return None
