def parse_retry_after(headers):
    """Parse the Retry-After header from HTTP response.

    The header can be either an integer number of seconds or a HTTP-date.
    This function returns the number of seconds to wait.
    """
    # The header name is case-insensitive according to RFC 7231.
    # We need to handle different casings.
    # Try to get the header value.
    value = None
    for key in headers:
        if key.lower() == "retry-after":
            value = headers[key]
            break
    if value is None:
        return None
    # If the value is an integer, return it.
    try:
        return int(value)
    except ValueError:
        pass
    # If the value is a HTTP-date, parse it.
    from email.utils import parsedate_to_datetime
    try:
        dt = parsedate_to_datetime(value)
        # Return the difference between the date and now in seconds.
        import datetime
        now = datetime.datetime.now(datetime.timezone.utc)
        delta = dt - now
        return int(delta.total_seconds())
    except Exception:
        return None
